-- airport_kb：为西双版纳机场追加别名「西双版纳机场」
UPDATE airport_kb
SET aliases_airport = (SELECT ARRAY(SELECT DISTINCT unnest(aliases_airport || ARRAY['西双版纳机场'])))
WHERE airport_code = 'JHG';
